import type { ChapterData, Lang } from '@/lib/types'

// Generated by `npm run content:build`; each chapter is its own lazily loaded chunk.
const modules = import.meta.glob<{ default: ChapterData }>('./generated/*/*.json')

const cache = new Map<string, Promise<ChapterData>>()

export function loadChapter(lang: Lang, num: number): Promise<ChapterData> {
  const key = `./generated/${lang}/${String(num).padStart(2, '0')}.json`
  if (!cache.has(key)) {
    const load = modules[key]
    if (!load) return Promise.reject(new Error(`No ${lang} content for chapter ${num}`))
    cache.set(key, load().then((m) => m.default))
  }
  return cache.get(key)!
}

export const figUrl = (lang: Lang, file: string) => `${import.meta.env.BASE_URL}figs/${lang}/${file}`
